    // RENDER HISTORY
    // ══════════════════════════════════════════════════════════════
    async function loadRenderPage() {
        if (!state.currentProject) return;
        // Load shots from status board for selector
        try {
            if (!state.statusBoard) {
                const data = await api('/projects/' + state.currentProject.id + '/status-board');
                state.statusBoard = data;
            }
            const allShots = [];
            (state.statusBoard?.scenes || []).forEach(s => (s.shots || []).forEach(sh => allShots.push({ ...sh, scene_number: s.scene_number })));
            document.getElementById('renderShotSelect').innerHTML = '<option value="">Select shot...</option>' +
                allShots.map(s => `<option value="${s.id}">Sc${s.scene_number}/${esc(s.shot_code)}</option>`).join('');
            document.getElementById('renderTableWrap').innerHTML = '<p class="text-sm text-muted">Select a shot to view render history.</p>';
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function loadRenderHistory() {
        const shotId = document.getElementById('renderShotSelect').value;
        if (!shotId) return;
        try {
            const data = await api('/shots/' + shotId + '/renders');
            const renders = data.renders || [];
            document.getElementById('renderTableWrap').innerHTML = renders.length === 0 ?
                '<p class="text-sm text-muted">No renders for this shot.</p>' :
                `<table class="render-table">
                    <tr><th>Ver</th><th>Step</th><th>Model</th><th>Seed</th><th>Steps</th><th>Guidance</th><th>Mode</th><th>Duration</th><th>Date</th></tr>
                    ${renders.map(r => `<tr>
                        <td>${r.version}</td>
                        <td><span class="badge">${r.step}</span></td>
                        <td>${esc(r.model_id || '-')}</td>
                        <td>${r.seed ?? '-'}</td>
                        <td>${r.steps || '-'}</td>
                        <td>${r.guidance || '-'}</td>
                        <td><span class="badge ${r.mode === 'locked' ? 'approved' : ''}">${r.mode}</span></td>
                        <td>${r.inference_ms ? (r.inference_ms/1000).toFixed(1) + 's' : '-'}</td>
                        <td class="text-muted">${new Date(r.created_at).toLocaleDateString()}</td>
                    </tr>`).join('')}
                </table>`;
        } catch (err) { setStatus('Error: ' + err.message); }
    }
